using System.Collections.Generic;using UnityEngine;using UnityEngine.InputSystem.EnhancedTouch;
namespace AstroGateway.NativeSlice {
 public class AdaptiveTouch:MonoBehaviour {public ControlModeManager modes;public NativeSliceGame game;public bool preview=true,leftHanded;public float sensitivity=1,size=1,opacity=.75f;[System.NonSerialized]public NativeInput input;public Rect safe,move,enter,run,brake,scan,camera;readonly Dictionary<int,int> owners=new Dictionary<int,int>();Vector2 anchor;bool enhanced;ScreenOrientation prior;
 void OnEnable(){EnhancedTouchSupport.Enable();enhanced=true;prior=Screen.orientation;if(Application.platform==RuntimePlatform.Android)Screen.orientation=ScreenOrientation.LandscapeLeft;if(modes)modes.Changed+=OnMode;}
 void OnMode(ControlMode mode){Clear();}public void Clear(){owners.Clear();input=default;}
 public void Layout(Rect bottom,int width,int height){safe=new Rect(bottom.x,height-bottom.yMax,bottom.width,bottom.height);float s=Mathf.Clamp(size,.7f,1.5f)*Mathf.Min(safe.width/1280,safe.height/720);float d=160*s,gap=16*s;move=new Rect(leftHanded?safe.xMax-d-gap:safe.x+gap,safe.yMax-d-gap,d,d);enter=new Rect(leftHanded?safe.x+gap:safe.xMax-120*s-gap,safe.yMax-100*s-gap,120*s,100*s);run=new Rect(enter.x,enter.y-100*s-gap,120*s,100*s);brake=new Rect(enter.x+(leftHanded?130*s:-130*s),enter.y,120*s,100*s);scan=new Rect(brake.x,run.y,120*s,100*s);camera=new Rect(leftHanded?safe.x:safe.center.x,safe.y+190*s,safe.width/2,safe.height-190*s);}
 public void Finger(int id,Vector2 pos,Vector2 delta,bool begin,bool end){if(end){if(owners.TryGetValue(id,out int old)&&old==0)input.movement=Vector2.zero;owners.Remove(id);Flags();return;}if(begin&&!owners.ContainsKey(id)&&safe.Contains(pos)){int r=move.Contains(pos)?0:enter.Contains(pos)?1:run.Contains(pos)?2:brake.Contains(pos)?3:scan.Contains(pos)?4:camera.Contains(pos)?5:-1;if(r==5&&game&&game.DataPanel.Contains(pos))r=-1;if(r>=0&&!owners.ContainsValue(r)){owners[id]=r;if(r==0)anchor=pos;if(r==1&&game)game.Interact();if(r==4&&game)game.Scan();}}if(!owners.TryGetValue(id,out int region))return;if(region==0){var v=(pos-anchor)/(move.width*.4f);v.y=-v.y;input.movement=v.magnitude<.1f?Vector2.zero:Vector2.ClampMagnitude(v,1);}if(region==5)input.look+=new Vector2(delta.x,-delta.y)*Mathf.Clamp(sensitivity,.1f,3);Flags();}
 void Flags(){input.run=owners.ContainsValue(2);input.accelerate=modes&&modes.Mode==ControlMode.Rover&&input.run;input.brake=owners.ContainsValue(3);}
 public void Poll(){input.look=Vector2.zero;Layout(Screen.safeArea,Screen.width,Screen.height);foreach(var t in UnityEngine.InputSystem.EnhancedTouch.Touch.activeTouches){var p=t.screenPosition;Finger(t.touchId,new Vector2(p.x,Screen.height-p.y),new Vector2(t.delta.x,-t.delta.y),t.phase==UnityEngine.InputSystem.TouchPhase.Began,t.phase==UnityEngine.InputSystem.TouchPhase.Ended||t.phase==UnityEngine.InputSystem.TouchPhase.Canceled);}}
 void OnApplicationFocus(bool focus){if(!focus)Clear();}void OnApplicationPause(bool pause){if(pause)Clear();}
 void OnDisable(){Clear();if(modes)modes.Changed-=OnMode;if(enhanced){EnhancedTouchSupport.Disable();enhanced=false;}if(Application.platform==RuntimePlatform.Android)Screen.orientation=prior;}
 void OnGUI(){if(!preview&&Application.platform!=RuntimePlatform.Android)return;Layout(Screen.safeArea,Screen.width,Screen.height);GUI.color=new Color(1,1,1,Mathf.Clamp(opacity,.3f,1));GUI.Box(move,"FLOAT MOVE / STEER");GUI.Box(enter,modes&&modes.Mode==ControlMode.Rover?"EXIT":"BOARD");GUI.Box(run,modes&&modes.Mode==ControlMode.Rover?"ACCELERATE":"RUN");GUI.Box(brake,"BRAKE");GUI.Box(scan,"SCAN");GUI.color=Color.white;}
 }
}
